#include <stdio.h>

/* escreva AQUI EMBAIXO as DUAS caixas, cada uma com as MESMAS duas janelas:

   int area(int largura, int altura)       -> devolve largura vezes altura
   int perimetro(int largura, int altura)  -> devolve 2 * (largura + altura)

   as duas DEVOLVEM o valor; nenhuma delas imprime. */

