#include <stdio.h>

/* teste do desafio area-e-perimetro — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   Fase VALOR: o teste declara os prototipos das caixas do aluno no topo e
   confere o RETORNO com checa_int — nenhuma captura de stdout aqui. Dois
   retangulos por cenario: um numero fixo no return nao passa nos dois. */

/* prototipos das funcoes do aluno (o teste declara o que exercita) */
int area(int largura, int altura);
int perimetro(int largura, int altura);

/* cenario 1 — a area usa as duas janelas na multiplicacao */
SM_TEST(a_area_e_largura_por_altura) {
    checa_int("a area de 3 por 5", area(3, 5), 15,
              "a area do retangulo e largura vezes altura");
    checa_int("a area de 2 por 7", area(2, 7), 14,
              "outro retangulo, outra area: as duas janelas entram na conta");
}

/* cenario 2 — o perimetro usa as MESMAS duas janelas em outra conta */
SM_TEST(o_perimetro_e_o_contorno) {
    checa_int("o perimetro de 3 por 5", perimetro(3, 5), 16,
              "o contorno e 2 vezes a soma dos dois lados");
    checa_int("o perimetro de 2 por 7", perimetro(2, 7), 18,
              "o mesmo par de janelas do cenario 1, com o trabalho de dentro trocado");
}

solutionCode:
#include <stdio.h>

int area(int largura, int altura) {
    return largura * altura;
}

int perimetro(int largura, int altura) {
    return 2 * (largura + altura);
}
